/**
 * Audi Lab: the Audi A3 Sportback 8V (S line, 2.0 TDI) on its own, in a dark studio, away from
 * the site. The model is the Blender-built asset of the `audi` repository
 * (assets/audi/a3_sportback_8v.glb, generated by its src/a3/ and tools/run.py): 1:1, metres,
 * glTF axes with +X forward and +Y up, origin on the ground under the front axle. Its 45
 * assembly groups are the "G_<id>" nodes, each with glTF extras — group, label (Spanish) and
 * explode, a vector in metres — which is what the exploded view moves them along.
 *
 * Nothing here is loaded until the lab is first opened: the 56 MB file is not on the start-up
 * path. The lab has its own scene, camera, lights and environment map and draws with the
 * site's renderer while it is open (main.js skips its own frame), so the site keeps its state
 * and comes back as it was left.
 *
 * What moves is animation, not simulation: the groups slide along their explode vectors and the
 * doors, bonnet and tailgate turn about hinge lines estimated from each panel's bounding box.
 *
 * The lab's own text is in Spanish (the asset's labels are), by the owner's choice.
 */
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';

export const AUDI_ASSET = new URL('../../assets/audi/a3_sportback_8v.glb', import.meta.url);

const WHEELBASE = 2.636;          // m: the asset's origin is the front axle; the lab centres the car
const EXPLODE_GAIN = 1.45;        // the asset's vectors are for a tight view; the lab has room

/** The asset's groups by category, in the order they are listed. */
const CATEGORIES = [
  ['Carrocería', ['carroceria', 'capo', 'rejilla_parabrisas', 'paragolpes_del', 'aleta_izq', 'aleta_der',
    'puerta_di', 'puerta_dd', 'puerta_ti', 'puerta_td', 'faldon_izq', 'faldon_der', 'porton', 'paragolpes_tras']],
  ['Cristales e iluminación', ['parabrisas', 'custodia_izq', 'custodia_der', 'faro_izq', 'faro_der', 'piloto_izq', 'piloto_der']],
  ['Ruedas y frenos', ['rueda_di', 'rueda_dd', 'rueda_ti', 'rueda_td', 'freno_di', 'freno_dd', 'freno_ti', 'freno_td']],
  ['Mecánica', ['motor', 'suspension', 'escape', 'bajos']],
  ['Interior', ['salpicadero', 'volante', 'consola', 'asiento_di', 'asiento_dd', 'asiento_tras', 'pedales',
    'techo_interior', 'guarnecidos', 'cinturones', 'suelo', 'maletero']],
];

/**
 * Hinged panels. `edge` says where on the group's bounding box the hinge line is, `axis` its
 * direction (lab axes: X forward, Y up, Z to the car's right) and `open` the angle in degrees.
 * Estimates: the asset carries no hinge data.
 */
const HINGES = {
  puerta_di: { edge: ['max', 'mid', 'min'], axis: [0, 1, 0], open: -58 },
  puerta_dd: { edge: ['max', 'mid', 'max'], axis: [0, 1, 0], open: 58 },
  puerta_ti: { edge: ['max', 'mid', 'min'], axis: [0, 1, 0], open: -55 },
  puerta_td: { edge: ['max', 'mid', 'max'], axis: [0, 1, 0], open: 55 },
  capo: { edge: ['min', 'max', 'mid'], axis: [0, 0, 1], open: 48 },
  porton: { edge: ['max', 'max', 'mid'], axis: [0, 0, 1], open: -72 },
};
const OPENINGS = [
  ['Puertas', ['puerta_di', 'puerta_dd', 'puerta_ti', 'puerta_td']],
  ['Capó', ['capo']],
  ['Portón', ['porton']],
];

/** Camera stations, in the lab's frame (car centred, nose to +X; the driver sits at −Z). */
const VIEWS = [
  ['3/4 delantera', [4.5, 1.55, -3.6], [0, 0.62, 0]],
  ['Lateral', [0, 1.0, -6.4], [0, 0.66, 0]],
  ['Frontal', [6.4, 1.0, 0], [0, 0.66, 0]],
  ['3/4 trasera', [-4.6, 1.7, 3.5], [0, 0.66, 0]],
  ['Trasera', [-6.4, 1.05, 0], [0, 0.7, 0]],
  ['Superior', [-0.01, 7.6, 0], [0, 0.5, 0]],
  ['Rueda', [1.95, 0.5, -2.1], [1.32, 0.31, -0.78]],
  ['Motor', [3.3, 2.15, -0.9], [1.25, 0.78, 0], { open: ['capo'] }],
  ['Interior', [-0.42, 1.17, -0.37], [0.45, 0.93, -0.2]],
  ['Maletero', [-4.4, 1.9, 0.7], [-1.9, 0.75, 0], { open: ['porton'] }],
];

const ease = (t) => t * t * (3 - 2 * t);

/** A softbox studio, for the reflections: a dark room with a few bright panels. */
function studioEnvironment(renderer) {
  const s = new THREE.Scene();
  s.add(new THREE.Mesh(new THREE.BoxGeometry(40, 20, 40), new THREE.MeshBasicMaterial({ color: 0x24262b, side: THREE.BackSide })));
  const panel = (w, h, pos, k, tint = 0xffffff) => {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({ color: new THREE.Color(tint).multiplyScalar(k), side: THREE.DoubleSide }));
    m.position.set(...pos); m.lookAt(0, 0.6, 0); s.add(m);
  };
  panel(14, 7, [0, 9.5, 0], 7);                    // overhead softbox: the long highlight on roof and shoulders
  panel(16, 2.2, [0, 3.2, -11], 5);                // strips along both sides: the lines on the flanks
  panel(16, 2.2, [0, 3.2, 11], 5);
  panel(7, 3.5, [12, 4.5, 0], 4, 0xfff4e6);        // front and rear fills
  panel(7, 3.5, [-12, 4.5, 0], 3, 0xe8f0ff);
  const floor = new THREE.Mesh(new THREE.PlaneGeometry(40, 40), new THREE.MeshBasicMaterial({ color: 0x101114 }));
  floor.rotation.x = -Math.PI / 2; floor.position.y = -0.01; s.add(floor);
  const pmrem = new THREE.PMREMGenerator(renderer);
  const tex = pmrem.fromScene(s, 0.03).texture;
  pmrem.dispose();
  s.traverse(o => { o.geometry?.dispose(); o.material?.dispose(); });
  return tex;
}

export function createAudiLab({ renderer, onExit }) {
  const lab = { active: false, loaded: false };
  let root = null, stage = null, ui = null;
  let scene = null, camera = null, controls = null, composer = null, rt = null, key = null;
  let car = null;
  const groups = new Map();     // id -> { node, p0, q0, dir, delay, hinge, open, openTo, row, visible }
  const pickables = [];
  let explode = 0, explodeTo = 0;
  let selected = null, selBox = null, isolated = null;
  let camTween = null;
  let dirty = true, shadowDirty = true;
  let saved = null;
  const raycaster = new THREE.Raycaster(), ndc = new THREE.Vector2();
  const _v = new THREE.Vector3(), _q = new THREE.Quaternion(), _b = new THREE.Box3();

  // ---- DOM ----
  function buildDom() {
    root = document.createElement('div');
    root.id = 'audi-lab';
    root.className = 'hidden';
    root.innerHTML = `
      <div class="al-stage" aria-label="Audi A3 Sportback: vista 3D. Arrastra para girar, rueda o pellizco para acercar"></div>
      <header class="al-head">
        <button class="tool tool-btn al-back" type="button" title="Volver al centro de vehículos (Esc)">← Volver</button>
        <div class="al-title">
          <div class="eyebrow">Audi Lab</div>
          <div class="al-name">Audi A3 Sportback 8V</div>
          <div class="al-sub">S line · 2.0 TDI 150 CV · S tronic · 2013–2016</div>
        </div>
      </header>
      <aside class="al-panel" aria-label="Despiece y piezas">
        <button class="tool tool-btn al-panel-toggle" type="button" aria-expanded="true">Piezas</button>
        <div class="al-panel-body">
          <label class="al-row al-explode"><span>Despiece</span><output>0 %</output>
            <input type="range" min="0" max="100" value="0" step="1" aria-label="Separación del despiece"></label>
          <div class="al-actions">
            <button class="tool tool-btn" type="button" data-act="assemble" title="Montar el coche: sin despiece, todo visible y cerrado">Montar</button>
            <button class="tool tool-btn" type="button" data-act="showall">Mostrar todo</button>
          </div>
          <div class="al-openings"></div>
          <div class="al-groups"></div>
        </div>
      </aside>
      <nav class="al-views" aria-label="Vistas"></nav>
      <div class="al-tag hidden" role="status" aria-live="polite"><b></b><small></small></div>
      <div class="al-loading" role="status" aria-live="polite">
        <div class="loading-card">
          <div class="eyebrow">Audi Lab</div>
          <div class="loading-title">Cargando el Audi A3 a escala 1:1</div>
          <div class="loading-track"><div class="loading-fill"></div></div>
          <div class="loading-text">Descargando el modelo…</div>
        </div>
      </div>`;
    document.body.appendChild(root);
    stage = root.querySelector('.al-stage');
    ui = {
      slider: root.querySelector('.al-explode input'), out: root.querySelector('.al-explode output'),
      groups: root.querySelector('.al-groups'), openings: root.querySelector('.al-openings'),
      views: root.querySelector('.al-views'), tag: root.querySelector('.al-tag'),
      loading: root.querySelector('.al-loading'), fill: root.querySelector('.al-loading .loading-fill'),
      text: root.querySelector('.al-loading .loading-text'), panel: root.querySelector('.al-panel'),
    };
    root.querySelector('.al-back').addEventListener('click', () => lab.close());
    ui.slider.addEventListener('input', () => setExplode(ui.slider.value / 100));
    root.querySelector('[data-act="assemble"]').addEventListener('click', assemble);
    root.querySelector('[data-act="showall"]').addEventListener('click', showAll);
    const toggle = root.querySelector('.al-panel-toggle');
    toggle.addEventListener('click', () => {
      const shut = ui.panel.classList.toggle('is-shut');
      toggle.setAttribute('aria-expanded', String(!shut));
    });
    if (window.innerWidth < 760) { ui.panel.classList.add('is-shut'); toggle.setAttribute('aria-expanded', 'false'); }
    for (const [name, pos, target, opts] of VIEWS) {
      const b = document.createElement('button');
      b.type = 'button'; b.className = 'tool tool-btn'; b.textContent = name;
      b.addEventListener('click', () => { for (const id of opts?.open ?? []) setOpen(id, true); flyTo(pos, target); });
      ui.views.appendChild(b);
    }
    // A click that did not drag picks the part under it.
    let down = null;
    stage.addEventListener('pointerdown', (e) => { down = { x: e.clientX, y: e.clientY, t: performance.now() }; camTween = null; });
    stage.addEventListener('pointerup', (e) => {
      if (!down) return;
      const moved = Math.hypot(e.clientX - down.x, e.clientY - down.y), held = performance.now() - down.t;
      down = null;
      if (moved < 6 && held < 500) pick(e.clientX, e.clientY);
    });
  }

  // ---- Scene ----
  function buildScene() {
    scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0b0c0e);
    scene.fog = new THREE.Fog(0x0b0c0e, 9, 26);
    scene.environment = studioEnvironment(renderer);
    scene.environmentIntensity = 0.7;
    camera = new THREE.PerspectiveCamera(36, window.innerWidth / window.innerHeight, 0.03, 120);
    camera.position.set(...VIEWS[0][1]);
    controls = new OrbitControls(camera, stage);
    controls.target.set(...VIEWS[0][2]);
    controls.enableDamping = true; controls.dampingFactor = 0.08;
    controls.minDistance = 0.12; controls.maxDistance = 16;
    controls.maxPolarAngle = Math.PI * 0.497;      // not under the floor
    controls.zoomToCursor = true;
    controls.addEventListener('change', () => { dirty = true; });

    key = new THREE.DirectionalLight(0xffffff, 2.2);
    key.position.set(3.5, 9, -4.5);
    key.castShadow = true;
    key.shadow.mapSize.set(4096, 4096);
    Object.assign(key.shadow.camera, { left: -5.5, right: 5.5, top: 5.5, bottom: -5.5, near: 1, far: 22 });
    key.shadow.bias = -0.0002; key.shadow.normalBias = 0.012; key.shadow.radius = 5;
    scene.add(key);
    const rim = new THREE.DirectionalLight(0xdfe8ff, 0.7);
    rim.position.set(-6, 4, 5); scene.add(rim);

    const floor = new THREE.Mesh(new THREE.CircleGeometry(34, 96),
      new THREE.MeshStandardMaterial({ color: 0x0d0e11, roughness: 0.92, metalness: 0.0, envMapIntensity: 0.25 }));
    floor.rotation.x = -Math.PI / 2; floor.receiveShadow = true; floor.name = 'audi-lab-floor';
    scene.add(floor);

    // Same as the site's: a multisampled half-float target and one output pass (tone mapping).
    rt = new THREE.WebGLRenderTarget(window.innerWidth, window.innerHeight, { samples: 4, type: THREE.HalfFloatType });
    composer = new EffectComposer(renderer, rt);
    composer.addPass(new RenderPass(scene, camera));
    composer.addPass(new OutputPass());
    composer.setSize(window.innerWidth, window.innerHeight);
  }

  // ---- Asset ----
  async function fetchAsset() {
    const res = await fetch(AUDI_ASSET);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const total = Number(res.headers.get('content-length')) || 0;
    if (!res.body || !total) return res.arrayBuffer();
    const data = new Uint8Array(total), reader = res.body.getReader();
    let got = 0;
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      if (got + value.length > total) return (await fetch(AUDI_ASSET)).arrayBuffer();   // a compressed transfer: sizes do not match
      data.set(value, got); got += value.length;
      ui.fill.style.width = `${(got / total * 90).toFixed(1)}%`;
      ui.text.textContent = `Descargando el modelo… ${(got / 1048576).toFixed(0)} / ${(total / 1048576).toFixed(0)} MB`;
    }
    return data.buffer;
  }

  function adopt(gltf) {
    const model = gltf.scene;
    model.updateMatrixWorld(true);
    model.traverse((o) => {
      if (o.userData?.explode && o.userData.group) {
        const g = o.userData.group, d = o.userData.explode;
        // Doors, wheels and lamps leave first; the shell, which everything hangs from, last.
        const delay = /puerta|rueda|faro|piloto|capo|porton/.test(g) ? 0 : (/carroceria|suelo/.test(g) ? 0.25 : 0.1);
        const e = { id: g, node: o, label: o.userData.label ?? g, p0: o.position.clone(), q0: o.quaternion.clone(),
          dir: new THREE.Vector3(d[0], d[1], d[2]).multiplyScalar(EXPLODE_GAIN), delay, hinge: null, open: 0, openTo: 0, visible: true, row: null };
        const h = HINGES[g];
        if (h) {
          _b.setFromObject(o);
          if (!_b.isEmpty()) {
            const c = _b.getCenter(new THREE.Vector3());
            const at = (k, i) => (k === 'min' ? _b.min : k === 'max' ? _b.max : c).getComponent(i);
            e.hinge = { pivot: new THREE.Vector3(at(h.edge[0], 0), at(h.edge[1], 1), at(h.edge[2], 2)), axis: new THREE.Vector3(...h.axis), angle: THREE.MathUtils.degToRad(h.open) };
          }
        }
        groups.set(g, e);
      }
      if (!o.isMesh) return;
      o.castShadow = true; o.receiveShadow = true;
      pickables.push(o);
      for (const m of [].concat(o.material)) {
        if (!m) continue;
        // Anisotropy needs tangents from UVs: the turned faces without them would draw black.
        if (m.anisotropy > 0 && !o.geometry.attributes.uv) m.anisotropy = 0;
        if (/^LED_|Lamp_LightGuide|Gauge_Marks|Needle|Screen_UI|Screen_MMI|Cluster_|Climate_LCD/.test(m.name) && m.emissive && !m.userData.lit) {
          m.userData.lit = true;
          if (m.emissive.getHex() === 0) m.emissive.copy(m.color);
          m.emissiveIntensity = Math.max(m.emissiveIntensity || 0, /^LED_/.test(m.name) ? 3 : 1.1);
        }
        if (/Glass|Lens/.test(m.name)) { m.transparent = true; m.depthWrite = false; o.castShadow = false; }
      }
    });
    car = new THREE.Group();
    car.name = 'audi-a3';
    car.position.x = WHEELBASE / 2;      // the origin under the front axle -> the car centred
    car.add(model);
    scene.add(car);
    selBox = new THREE.Box3Helper(new THREE.Box3(), 0xd7a24a);
    selBox.visible = false; selBox.material.depthTest = false; selBox.material.transparent = true; selBox.material.opacity = 0.9;
    scene.add(selBox);
  }

  function buildLists() {
    for (const [name, ids] of OPENINGS) {
      if (!ids.some(id => groups.get(id)?.hinge)) continue;
      const b = document.createElement('button');
      b.type = 'button'; b.className = 'tool tool-btn'; b.textContent = name; b.setAttribute('aria-pressed', 'false');
      b.addEventListener('click', () => { const on = b.getAttribute('aria-pressed') !== 'true'; for (const id of ids) setOpen(id, on); });
      b.dataset.ids = ids.join(',');
      ui.openings.appendChild(b);
    }
    const listed = new Set();
    const section = (name, ids) => {
      const present = ids.filter(id => groups.has(id));
      if (!present.length) return;
      const det = document.createElement('details');
      det.open = name === 'Carrocería';
      det.innerHTML = `<summary>${name} <span>${present.length}</span></summary>`;
      const ul = document.createElement('ul');
      for (const id of present) {
        listed.add(id);
        const g = groups.get(id), li = document.createElement('li');
        li.innerHTML = `<input type="checkbox" checked aria-label="Mostrar ${g.label}"><button type="button" class="al-pick">${g.label}</button><button type="button" class="al-iso" title="Aislar: ver solo esta pieza" aria-pressed="false">Aislar</button>`;
        li.querySelector('input').addEventListener('change', (e) => { setVisible(id, e.target.checked); });
        li.querySelector('.al-pick').addEventListener('click', () => select(id, null, true));
        li.querySelector('.al-iso').addEventListener('click', () => isolate(isolated === id ? null : id));
        g.row = li; ul.appendChild(li);
      }
      det.appendChild(ul); ui.groups.appendChild(det);
    };
    for (const [name, ids] of CATEGORIES) section(name, ids);
    section('Otros', [...groups.keys()].filter(id => !listed.has(id)));   // a group a later asset adds
  }

  // ---- State ----
  function setExplode(k) {
    explodeTo = THREE.MathUtils.clamp(k, 0, 1);
    ui.slider.value = String(Math.round(explodeTo * 100));
    ui.out.textContent = `${Math.round(explodeTo * 100)} %`;
    // The exploded car is two or three times the size of the car: step back to keep it in frame.
    if (camera && !isolated) {
      const want = 7.2 + 6.5 * explodeTo, dir = _v.copy(camera.position).sub(controls.target);
      if (dir.length() < want) flyTo(dir.setLength(want).add(controls.target).toArray(), controls.target.toArray(), 0.7);
    }
    dirty = true;
  }
  function setOpen(id, on) {
    const g = groups.get(id);
    if (!g?.hinge) return;
    g.openTo = on ? 1 : 0;
    for (const b of ui.openings.children) {
      const ids = b.dataset.ids.split(',');
      b.setAttribute('aria-pressed', String(ids.every(i => groups.get(i)?.openTo === 1)));
    }
    dirty = true;
  }
  function setVisible(id, on) {
    const g = groups.get(id);
    if (!g) return;
    g.visible = on; g.node.visible = on;
    g.row.querySelector('input').checked = on;
    if (!on && selected === id) select(null);
    dirty = shadowDirty = true;
  }
  function isolate(id) {
    isolated = id;
    for (const g of groups.values()) {
      setVisible(g.id, !id || g.id === id);
      g.row.querySelector('.al-iso').setAttribute('aria-pressed', String(g.id === id));
    }
    if (id) select(id, null, true);
  }
  function showAll() { isolate(null); }
  /** The car as built: every group home, shown and shut. Positions are absolute, so nothing drifts. */
  function assemble() {
    showAll(); setExplode(0);
    for (const id of groups.keys()) setOpen(id, false);
    select(null);
  }

  function select(id, partLabel = null, frame = false) {
    selected = id && groups.has(id) ? id : null;
    for (const g of groups.values()) g.row.classList.toggle('is-selected', g.id === selected);
    if (!selected) { ui.tag.classList.add('hidden'); selBox.visible = false; dirty = true; return; }
    const g = groups.get(selected);
    ui.tag.querySelector('b').textContent = partLabel ?? g.label;
    ui.tag.querySelector('small').textContent = partLabel && partLabel !== g.label ? g.label : '';
    ui.tag.classList.remove('hidden');
    g.row.closest('details').open = true;
    g.row.scrollIntoView({ block: 'nearest' });
    if (frame) {
      _b.setFromObject(g.node);
      if (!_b.isEmpty()) {
        const c = _b.getCenter(new THREE.Vector3()), r = Math.max(0.35, _b.getSize(_v).length() / 2);
        const dist = r / Math.sin(THREE.MathUtils.degToRad(camera.fov) / 2) * 1.15;
        const dir = _v.copy(camera.position).sub(controls.target).normalize();
        flyTo(c.clone().addScaledVector(dir, dist).toArray(), c.toArray());
      }
    }
    dirty = true;
  }

  function pick(x, y) {
    if (!car) return;
    const r = stage.getBoundingClientRect();
    ndc.set(((x - r.left) / r.width) * 2 - 1, -((y - r.top) / r.height) * 2 + 1);
    raycaster.setFromCamera(ndc, camera);
    // Glass is see-through: the part behind it is the one meant, unless the glass is all there is.
    const hits = raycaster.intersectObjects(pickables, false).filter(h => { for (let p = h.object; p; p = p.parent) if (!p.visible) return false; return true; });
    const solid = hits.find(h => ![].concat(h.object.material).every(m => m.transparent)) ?? hits[0];
    if (!solid) { select(null); return; }
    let gid = null;
    for (let p = solid.object; p; p = p.parent) if (p.userData?.group && groups.has(p.userData.group)) { gid = p.userData.group; break; }
    select(gid, solid.object.userData.label ?? null);
  }

  function flyTo(pos, target, seconds = 0.9) {
    camTween = { t: 0, d: seconds, p0: camera.position.clone(), t0: controls.target.clone(), p1: new THREE.Vector3(...pos), t1: new THREE.Vector3(...target) };
  }

  function applyPose(g) {
    const k = THREE.MathUtils.clamp((explode - g.delay * 0.4) / (1 - g.delay * 0.4), 0, 1);
    g.node.position.copy(g.p0); g.node.quaternion.copy(g.q0);
    if (g.hinge && g.open > 0) {
      _q.setFromAxisAngle(g.hinge.axis, g.hinge.angle * ease(g.open));
      g.node.position.sub(g.hinge.pivot).applyQuaternion(_q).add(g.hinge.pivot);
      g.node.quaternion.premultiply(_q);
    }
    g.node.position.addScaledVector(g.dir, ease(k));
  }

  /** One frame of the lab, drawn only when something changed. */
  lab.render = (dt) => {
    if (!lab.active || !scene) return;
    const step = Math.min(dt, 0.05);
    let moving = false;
    if (Math.abs(explodeTo - explode) > 1e-4) { explode += (explodeTo - explode) * Math.min(1, step * 6); moving = true; } else explode = explodeTo;
    for (const g of groups.values()) {
      if (g.open !== g.openTo) { g.open = THREE.MathUtils.clamp(g.open + Math.sign(g.openTo - g.open) * step / 0.9, 0, 1); if (Math.abs(g.open - g.openTo) < 1e-3) g.open = g.openTo; moving = true; }
    }
    if (moving || shadowDirty) { for (const g of groups.values()) applyPose(g); shadowDirty = true; dirty = true; }
    if (camTween) {
      camTween.t = Math.min(1, camTween.t + step / camTween.d);
      const k = ease(camTween.t);
      camera.position.lerpVectors(camTween.p0, camTween.p1, k);
      controls.target.lerpVectors(camTween.t0, camTween.t1, k);
      if (camTween.t >= 1) camTween = null;
      dirty = true;
    }
    controls.update();
    if (!dirty) return;
    if (selected && selBox) { selBox.box.setFromObject(groups.get(selected).node); selBox.visible = !selBox.box.isEmpty(); }
    if (shadowDirty) { renderer.shadowMap.needsUpdate = true; shadowDirty = false; }
    composer.render();
    dirty = false;
  };

  function resize() {
    if (!scene) return;
    const w = window.innerWidth, h = window.innerHeight;
    camera.aspect = w / h; camera.updateProjectionMatrix();
    composer.setSize(w, h);
    dirty = true;
  }

  const onKey = (e) => {
    // The site's shortcuts (G launches Starship…) and its camera keys stay out of the lab.
    const t = e.target;
    if (t.tagName === 'INPUT' && t.type !== 'range' && t.type !== 'checkbox') return;
    e.stopImmediatePropagation();
    if (e.type !== 'keydown' || e.repeat || e.ctrlKey || e.metaKey || e.altKey) return;
    if (e.key === 'Escape') { if (isolated || selected) { showAll(); select(null); } else lab.close(); }
    else if (e.key.toLowerCase() === 'e') setExplode(explodeTo > 0.5 ? 0 : 1);
    else if (e.key.toLowerCase() === 'm') assemble();
  };

  lab.open = async () => {
    if (lab.active) return;
    if (!root) buildDom();
    lab.active = true;
    saved = { exposure: renderer.toneMappingExposure, autoUpdate: renderer.shadowMap.autoUpdate };
    renderer.toneMappingExposure = 0.82;
    renderer.shadowMap.autoUpdate = false;
    document.body.classList.add('audi-lab-open');
    root.classList.remove('hidden');
    window.addEventListener('keydown', onKey, true);
    window.addEventListener('keyup', onKey, true);
    window.addEventListener('resize', resize);
    if (!scene) buildScene();
    resize(); shadowDirty = dirty = true;
    root.querySelector('.al-back').focus();
    if (lab.loaded || lab.loading) return;
    lab.loading = true;
    try {
      const t0 = performance.now();
      const buf = await fetchAsset();
      ui.fill.style.width = '92%'; ui.text.textContent = 'Preparando geometría y materiales…';
      await new Promise(r => requestAnimationFrame(() => setTimeout(r, 30)));
      const gltf = await new GLTFLoader().parseAsync(buf, '');
      adopt(gltf); buildLists();
      lab.loaded = true;
      lab.stats = { seconds: (performance.now() - t0) / 1000, groups: groups.size, meshes: pickables.length };
      ui.loading.classList.add('hidden');
      shadowDirty = dirty = true;
    } catch (e) {
      console.warn(`Audi asset not loaded (${e.message})`);
      ui.fill.style.width = '0%';
      ui.text.textContent = `No se ha podido cargar el modelo (${e.message}). Vuelve e inténtalo de nuevo.`;
    } finally { lab.loading = false; }
  };

  lab.close = () => {
    if (!lab.active) return;
    lab.active = false;
    renderer.toneMappingExposure = saved.exposure;
    renderer.shadowMap.autoUpdate = saved.autoUpdate;
    renderer.shadowMap.needsUpdate = true;
    document.body.classList.remove('audi-lab-open');
    root.classList.add('hidden');
    window.removeEventListener('keydown', onKey, true);
    window.removeEventListener('keyup', onKey, true);
    window.removeEventListener('resize', resize);
    onExit?.();
  };

  // For the checks and the console.
  Object.assign(lab, { setExplode, setOpen, setVisible, isolate, showAll, assemble, select, groups });
  Object.defineProperties(lab, {
    explode: { get: () => explode }, camera: { get: () => camera }, scene: { get: () => scene }, car: { get: () => car },
  });
  return lab;
}
